('6908699', 'individual', 'Abdifatah Abubakar Abdi', 'ABDIFATAH ABUBAKAR ABDI', 'Somalia', 'SOi.017', '2018-03-08', 'Somalia', 'Somalia; Mombasa, Kenya', 'INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908853', 'individual', 'ABUKAR ALI ADAN', 'ABUKAR ALI ADAN', 'Somalia', 'SOi.018', '2021-02-26', NULL, NULL, 'Listed pursuant to paragraph 8(a) of resolution 1844 (2008) as “Engaging in or providing support for acts that threaten the peace, security or stability of Somalia, including acts that threaten the Djibouti Agreement of 18 August 2008 or the political process, or threaten the TFIs or AMISOM by force.” Adan is also associated with Al-Qaida affiliates, Al-Qaida in the Arabian Peninsula (AQAP – QDe.129) and Al-Qaida in the Islamic Maghreb (AQIM – Qde.014). INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908854', 'individual', 'MAALIM AYMAN', 'MAALIM AYMAN', 'Somalia', 'SOi.019', '2021-02-26', NULL, 'Kenya/Somalia border; Badamadow, Lower Juba Region, Somalia', 'Listed pursuant to paragraph 8(a) of resolution 1844 (2008) as “Engaging in or providing support for acts that threaten the peace, security or stability of Somalia, including acts that threaten the Djibouti Agreement of 18 August 2008 or the political process, or threaten the TFIs or AMISOM by force.” Ayman helped with preparations for the 5 January 2020 attack on Camp Simba in Lamu County, Kenya. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908855', 'individual', 'MAHAD KARATE', 'MAHAD KARATE', 'Somalia', 'SOi.020', '2021-02-26', NULL, 'Somalia', 'Listed pursuant to paragraph 8(a) of resolution 1844 (2008) as “Engaging in or providing support for acts that threaten the peace, security or stability of Somalia, including acts that threaten the Djibouti Agreement of 18 August 2008 or the political process, or threaten the TFIs or AMISOM by force.” Karate played a key role in the Amniyat, the wing of al-Shabaab responsible for the recent attack on Garissa University College in Kenya that resulted in nearly 150 deaths. The Amniyat is al-Shabaab’s intelligence wing, which plays a key role in the execution of suicide attacks and assassinations in Somalia, Kenya, and other countries in the region, and provides logistics and support for al-Shabaab’s terrorist activities. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908868', 'individual', 'ALI MOHAMED RAGE', 'ALI MUHAMMAD RAGE', 'Somalia', 'SOi.021', '2022-02-18', 'Somalia', 'Somalia', 'Listed pursuant to paragraph 43(a) of resolution 2093 (2013) as “Engaging in or providing support for acts that threaten the peace, security or stability of Somalia, including acts that threaten the peace and reconciliation process in Somalia, or threaten the Federal Government of Somalia or AMISOM by force.” As a spokesperson for Al-Shabaab, Rage is involved in promulgating and supporting the group’s terrorist activities. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908907', 'individual', 'ABDULLAHI OSMAN MOHAMED CADDOW', 'ABDULLAHI OSMAN MUHAMMAD CADDOW', 'Somalia', 'SOi.022', '2023-05-26', 'Somalia', 'Somalia', 'Gender: Male.', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6909265', 'individual', 'ABDIKADIR MOHAMED ABDIKADIR', 'ABDIKADIR MUHAMMAD ABDIKADIR', 'Somalia', 'SOi.023', '2024-05-21', 'Somalia, Kenya', 'Somalia', 'Gender: Male. Listed pursuant to paragraph 26(b) of resolution 2662 (2022): (i) participating in the financing, planning, facilitating, preparing, or perpetrating of acts or activities by, in conjunction with, under the name of, on behalf of, or in support of Al-Shabaab and (iii) recruiting for, or otherwise supporting acts or activities of Al-Shabaab or any cell, affiliate, splinter group or derivative thereof. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6909266', 'individual', 'MOHAMED MOHAMUD MIRE', 'MUHAMMAD MOHAMUD MIRE', 'Somalia', 'SOi.024', '2024-05-21', 'Somalia', 'Jilib, Somalia; Qunyo Barrow, Somalia', 'Gender: Male. Listed pursuant to paragraph 26 of resolution 2662 (2022): (a) having engaged in, or provided support for, acts that threatened the peace, security or stability of Somalia, including acts that threatened the peace and reconciliation process in Somalia, or threatened the Federal Government of Somalia or ATMIS by force; and (b)(i) participating in the financing, planning, facilitating, preparing, or perpetrating of acts or activities by, in conjunction with, under the name of, on behalf of, or in support of Al-Shabaab. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6909267', 'individual', 'MOHAMED OMAR MOHAMED', 'MUHAMMAD OMAR MUHAMMAD', 'Somalia', 'SOi.025', '2024-05-21', NULL, 'Diinsor District, Bay Region, Somalia; Buur Hakaba District, Bay Region, Somalia', 'Gender: Male. Listed pursuant to paragraph 26(b) of resolution 2662 (2022): (i) participating in the financing, planning, facilitating, preparing, or perpetrating of acts or activities by, in conjunction with, under the name of, on behalf of, or in support of Al-Shabaab; and (iii) recruiting for, or otherwise supporting acts or activities of Al-Shabaab or any cell, affiliate, splinter group or derivative thereof. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908457', 'individual', 'GABRIEL JOK RIAK MAKOL', 'GABRIEL JOK RIAK MAKOL', 'SouthSudan', 'SSi.001', '2015-07-01-04:00', 'South Sudan', 'Unity State, South Sudan; Wau, Western Bahr El Ghazal, South Sudan', 'Appointed as Chief of Defence Forces on 2 May 2018. Commanded SPLA Sector One, which operates primarily within Unity State, since January 2013. In his position as the SPLA Sector One commander, he has expanded or extended the conflict in South Sudan through breaches of the Cessation of Hostilities Agreement. The SPLA is a South Sudanese military entity that has engaged in actions that have extended the conflict in South Sudan, including breaches of the January 2014 Cessation of Hostilities Agreement and the May 9, 2014 Agreement to Resolve the Crisis in South Sudan, which was a re-commitment to the CoHA and has obstructed the activities of IGAD’s Monitoring and Verification Mechanism. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908458', 'individual', 'SIMON GATWECH DUAL', 'SIMON GATWECH DUAL', 'SouthSudan', 'SSi.002', '2015-07-01-04:00', NULL, 'Jonglei State, Sudan; Jonglei State, South Sudan', 'Is the SPLM-IO Chief of General Staff and was previously the commander of opposition forces in Jonglei State. His forces conducted an early February 2015 attack in Jonglei State, and as of March 2015, he had tried to destroy the peace in Jonglei State through attacks on the civilian population. Photograph available for inclusion in the INTERPOL-UN Security Council Special Notice. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908461', 'individual', 'JAMES KOANG CHUOL', 'JAMES KOANG CHUOL', 'SouthSudan', 'SSi.003', '2015-07-01-04:00', 'South Sudan', NULL, 'Appointed commander of the Sudan People’s Liberation Army in Opposition (SPLA-IO) Special Division in December 2014. His forces have been engaged in attacks against civilians. In February 2014, forces under his command attacked United Nations camps, hospitals, churches, and schools, engaging in widespread rape, torture, and the destruction of property, in an attempt to flush out civilians, soldiers, and policemen allied with the government. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908459', 'individual', 'SANTINO DENG WOL', 'SANTINO DENG WOL', 'SouthSudan', 'SSi.004', '2015-07-01-04:00', NULL, NULL, 'Has led and directed military actions against opposition forces and conducted confrontational troop movements in violation of the CoHA. During May 2015, forces under his command killed children, women and old men, burned property, and stole livestock as they advanced through Unity State towards Thorjath oil field. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908460', 'individual', 'MARIAL CHANUONG YOL MANGOK', 'MARIAL CHANUONG YOL MANGOK', 'SouthSudan', 'SSi.005', '2015-07-01-04:00', 'South Sudan', NULL, 'His Presidential Guard led the slaughter of Nuer civilians in and around Juba, many who were buried in mass graves. One such grave was purported to contain 200-300 civilians. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908462', 'individual', 'PETER GADET', 'PETER GADET', 'SouthSudan', 'SSi.006', '2015-07-01-04:00', NULL, NULL, 'Appointed the SPLA-IO’s Deputy Chief of Staff for Operations on December 21, 2014. Forces under his command targeted civilians, including women, in April 2014 during an assault on Bentiu, including targeted killings on the basis of ethnicity. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908711', 'individual', 'MALEK REUBEN RIAK RENGU', 'MALEK REUBEN RIAK RENGU', 'SouthSudan', 'SSi.007', '2018-07-13', 'South Sudan', NULL, 'As SPLA Deputy Chief of Staff for Logistics, Riak was one of the senior officials of the Government of South Sudan who planned and oversaw an offensive in Unity state in 2015 that resulted in widespread destruction and large population displacement. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908714', 'individual', 'PAUL MALONG AWAN ANEI', 'PAUL MALONG AWAN ANEI', 'SouthSudan', 'SSi.008', '2018-07-13', 'South Sudan, Uganda', NULL, 'As Chief of General Staff of the SPLA, Malong expanded or extended the conflict in South Sudan through breaches of the Cessation of Hostilities Agreement and breaches of the 2015 Agreement on the Resolution of the Conflict in South Sudan (ARCSS). He reportedly directed efforts to kill opposition leader Riek Machar. He ordered SPLA units to prevent the transport of humanitarian supplies. Under Malong’s leadership, the SPLA attacked civilians, schools and hospitals; forced the displacement of civilians; carried out enforced disappearances; arbitrarily detained civilians; and conducted acts of torture, and rape. He mobilized the Mathiang Anyoor Dinka tribal militia, which uses child soldiers. Under his leadership, the SPLA restricted UNMISS, the Joint Monitoring and Evaluation Commission (JMEC), and CTSAMM access to sites to investigate and document abuses. INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110577', 'individual', 'MOHAMMAD HASSAN AKHUND', 'MOHAMMAD HASSAN AKHUND', 'Taliban', 'TAi.002', '2001-01-25', 'Afghanistan', 'Kabul, Afghanistan', 'A close associate of Mullah Mohammed Omar (TAi.004). Member of Taliban Supreme Council as at Dec. 2009. Belongs to Baabar tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110578', 'individual', 'ABDUL KABIR MOHAMMAD JAN', 'ABDUL KABIR MOHAMMAD JAN', 'Taliban', 'TAi.003', '2001-01-25', 'Afghanistan', 'Afghanistan', 'Active in terrorist operations in Eastern Afghanistan. Collects money from drug traffickers. Member of the Taliban Supreme Council as at 2009. Family is originally from Neka District, Paktia Province, Afghanistan. Responsible for attack on Afghan parliamentarians in November 2007 in Baghlan; owns land in central Baghlan Province. Belongs to Zadran tribe. Height 185 cm. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110579', 'individual', 'MOHAMMED OMAR GHULAM NABI', 'MUHAMMAD OMAR GHULAM NABI', 'Taliban', 'TAi.004', '2000-04-12', 'Afghanistan', NULL, 'Father''s name is Ghulam Nabi, also known as Mullah Musafir. Left eye missing. Brother-in-law of Ahmad Jan Akhundzada Shukoor Akhundzada (TAi.109). Believed to be in Afghanistan/Pakistan border area. Belongs to Hotak tribe. Reportedly deceased as of April 2013 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110447', 'individual', 'MUHAMMAD TAHER ANWARI', 'MUHAMMAD TAHER ANWARI', 'Taliban', 'TAi.005', '2001-02-23', 'Afghanistan', NULL, 'Belongs to Andar tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110580', 'individual', 'SAYYED MOHAMMED HAQQANI', 'SAYYED MUHAMMAD HAQQANI', 'Taliban', 'TAi.006', '2001-01-31', 'Afghanistan', NULL, 'Graduate of the Haqqaniya madrasa in Akora Khattak, Pakistan. Believed to have had close relations with Taliban Leader Mullah Mohammed Omar (TAi.004). Believed to be in Afghanistan/Pakistan border area. Member of Taliban Supreme Council as at June 2010. Belongs to Barakzai tribe. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice. Reportedly deceased as of January 2016 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110554', 'individual', 'ABDUL LATIF MANSUR', 'ABDUL LATIF MANSUR', 'Taliban', 'TAi.007', '2001-01-31', 'Afghanistan', 'Darul Aman, Kabul, Afghanistan', 'Taliban Shadow Governor for Logar Province as of late 2012. Belongs to Sahak tribe (Ghilzai). Height 170 cm. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('110896', 'individual', 'SHAMS UR-RAHMAN ABDUL ZAHIR', 'SHAMS UR RAHMAN ABDUL ZAHIR', 'Taliban', 'TAi.008', '2001-02-23', 'Afghanistan', NULL, 'Believed to be in Afghanistan/Pakistan border area. Involved in drug trafficking. Belongs to Ghilzai tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111034', 'individual', 'ATTIQULLAH AKHUND', 'ATTIQULLAH AKHUND', 'Taliban', 'TAi.009', '2001-02-23', 'Afghanistan', NULL, 'Member of Taliban Supreme Military Council as well as Taliban Supreme Council as at June 2010. Belongs to Popalzai tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111090', 'individual', 'AKHTAR MOHAMMAD MANSOUR SHAH MOHAMMED', 'AKHTAR MOHAMMAD MANSOUR SHAH MUHAMMAD', 'Taliban', 'TAi.011', '2001-01-25', 'Afghanistan', NULL, 'Involved in drug trafficking as of 2011, primarily through Gerd-e-Jangal, Afghanistan. Active in the provinces of Khost, Paktia and Paktika, Afghanistan as of May 2007. Taliban "Governor" of Kandahar as of May 2007. Deputy to Mullah Abdul Ghani Baradar (TAi.024) in the Taliban Supreme Council as of 2009. Taliban official responsible for four southern provinces of Afghanistan. Following the arrest of Mullah Baradar in February 2010 he was temporarily-in-charge of the Taliban Supreme Council. Believed to be in Afghanistan/Pakistan border area. Belongs to Ishaqzai tribe. Reportedly killed in May 2016 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
