('111180', 'individual', 'MOHAMMAD ALEEM NOORANI', 'MOHAMMAD ALEEM NOORANI', 'Taliban', 'TAi.138', '2001-01-25', 'Afghanistan', NULL, 'INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111238', 'individual', 'ABDUL GHAFAR SHINWARI', 'ABDUL GHAFAR SHINWARI', 'Taliban', 'TAi.139', '2001-01-25', 'Afghanistan', NULL, 'Believed to be in Afghanistan/Pakistan border area. Belongs to Safi tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111181', 'individual', 'GUL AHMAD HAKIMI', 'GUL AHMAD HAKIMI', 'Taliban', 'TAi.140', '2001-01-25', 'Afghanistan', NULL, 'Believed to be in Afghanistan/Pakistan border area INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111305', 'individual', 'ABDULLAH HAMAD MOHAMMAD KARIM', 'ABDULLAH HAMAD MOHAMMAD KARIM', 'Taliban', 'TAi.141', '2001-01-25', 'Afghanistan', NULL, 'Believed to be in Afghanistan/Pakistan border area. Belongs to Baloch ethnic group INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22')
ON CONFLICT(uid) DO UPDATE SET entity_type = excluded.entity_type, primary_name = excluded.primary_name, name_normalized = excluded.name_normalized, un_list_type = excluded.un_list_type, reference_number = excluded.reference_number, listed_on = excluded.listed_on, nationality = excluded.nationality, addresses = excluded.addresses, remarks = excluded.remarks, source_url = excluded.source_url, last_updated = excluded.last_updated WHERE un_sanctions_entries.entity_type IS NOT excluded.entity_type OR un_sanctions_entries.primary_name IS NOT excluded.primary_name OR un_sanctions_entries.name_normalized IS NOT excluded.name_normalized OR un_sanctions_entries.un_list_type IS NOT excluded.un_list_type OR un_sanctions_entries.reference_number IS NOT excluded.reference_number OR un_sanctions_entries.listed_on IS NOT excluded.listed_on OR un_sanctions_entries.nationality IS NOT excluded.nationality OR un_sanctions_entries.addresses IS NOT excluded.addresses OR un_sanctions_entries.remarks IS NOT excluded.remarks OR un_sanctions_entries.source_url IS NOT excluded.source_url;
INSERT INTO un_sanctions_entries (uid, entity_type, primary_name, name_normalized, un_list_type, reference_number, listed_on, nationality, addresses, remarks, source_url, source_tier, last_updated) VALUES
('111239', 'individual', 'ABDUL HAI HAZEM ABDUL QADER', 'ABDUL HAI HAZEM ABDUL QADER', 'Taliban', 'TAi.142', '2001-01-25', 'Afghanistan', 'Iltifat village, Shakardara District, Kabul Province, Afghanistan', 'INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('111182', 'individual', 'HAMDULLAH ALLAH NOOR', 'HAMDULLAH ALLAH NOOR', 'Taliban', 'TAi.143', '2001-01-25', 'Afghanistan', NULL, 'Believed to be in Afghanistan/Pakistan border area. Belongs to Baloch ethnic group. Additional title: Hafiz INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2785696', 'individual', 'SIRAJUDDIN JALLALOUDINE HAQQANI', 'SIRAJUDDIN JALLALOUDINE HAQQANI', 'Taliban', 'TAi.144', '2007-09-13', 'Afghanistan', 'Kabul, Afghanistan', 'Heading the Haqqani Network (TAe.012) as of late 2012. Son of Jalaluddin Haqqani (TAi.040). Belongs to Sultan Khel section, Zadran tribe of Garda Saray of Paktia province, Afghanistan. Height 187 cm or 180cm. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2913551', 'individual', 'AMIR ABDULLAH', 'AMIR ABDULLAH', 'Taliban', 'TAi.145', '2010-07-20', 'Afghanistan', 'Karachi, Pakistan', 'Has travelled to Kuwait, Saudi Arabia, the Libyan Arab Jamahiriya and the United Arab Emirates to raise funds for the Taliban. Treasurer to Abdul Ghani Baradar Abdul Ahmad Turk (TAi.024). Believed to be in Afghanistan/Pakistan border area INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2914108', 'individual', 'NASIRUDDIN HAQQANI', 'NASIRUDDIN HAQQANI', 'Taliban', 'TAi.146', '2010-07-20', 'Afghanistan', 'Pakistan', 'A leader of the Haqqani Network (TAe.012), which operates out of North Waziristan in the Federally Administered Tribal Areas of Pakistan. Son of Jalaluddin Haqqani (TAi.040). Has travelled to Saudi Arabia and the United Arab Emirates to raise funds for the Taliban. Reportedly deceased as of 2013 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2913442', 'individual', 'GUL AGHA ISHAKZAI', 'GUL AGHA ISHAKZAI', 'Taliban', 'TAi.147', '2010-07-20', 'Afghanistan', 'Ibni-Sina Watt, Kabul, Afghanistan', 'Head of Taliban Financial Commission as at mid-2013. Associated with Mullah Mohammed Omar (TAi.004). Served as Omar''s principal finance officer and one of his closest advisors. Belongs to Ishaqzai tribe. Height: 156 cm. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2945892', 'individual', 'ABDUL HABIB ALIZAI', 'ABDUL HABIB ALIZAI', 'Taliban', 'TAi.148', '2010-11-04', 'Afghanistan', NULL, 'Has managed a drug trafficking network in Helmand Province, Afghanistan. Has regularly traveled to Pakistan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2945562', 'individual', 'SALEH MOHAMMAD KAKAR AKHTAR MUHAMMAD', 'SALEH MOHAMMAD KAKAR AKHTAR MUHAMMAD', 'Taliban', 'TAi.149', '2010-11-04', 'Afghanistan', 'Daman District, Kandahar Province, Afghanistan', 'Has run an organized smuggling network in Kandahar and Helmand provinces, Afghanistan. Previously operated heroin processing laboratories in Band-e Temur, Kandahar Province, Afghanistan. Has owned a car dealership in Mirwais Mena, Dand District in Kandahar Province, Afghanistan. Released from custody in Afghanistan in February 2014. Linked by marriage to Mullah Ubaidullah Akhund Yar Mohammad Akhund (TAi.022). Belongs to Kakar tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2960150', 'individual', 'KHALIL AHMED HAQQANI', 'KHALIL AHMED HAQQANI', 'Taliban', 'TAi.150', '2011-02-09', 'Afghanistan', 'Sarana Zadran Village, Paktia Province, Afghanistan', 'Has previously traveled to, and raised funds in, Dubai, United Arab Emirates. Brother of Jalaluddin Haqqani (TAi.040) and uncle of Sirajuddin Jallaloudine Haqqani (TAi.144). Reportedly deceased as of 11 December 2024 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2975510', 'individual', 'FAIZULLAH KHAN NOORZAI na', 'FAIZULLAH KHAN NOORZAI NA', 'Taliban', 'TAi.153', '2011-10-04', 'Afghanistan', 'Boghra Road, Miralzei Village, Chaman, Baluchistan Province, Pakistan; Kalay Rangin, Spin Boldak District, Kandahar Province, Afghanistan', 'Prominent Taliban financier. As of mid-2009, supplied weapons, ammunition, explosives and medical equipment to Taliban fighters; and raised funds for the Taliban, and provided training to them, in the Afghanistan/Pakistan border region. Has previously organized and funded Taliban operations in Kandahar Province, Afghanistan. As of 2010, travelled to and owned businesses in Dubai, United Arab Emirates, and Japan. Belongs to Noorzai tribe, Miralzai sub-tribe. Brother of Malik Noorzai (TAi.154). Father’s name is Akhtar Mohammed (a.k.a.: Haji Mira Khan) INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2975590', 'individual', 'MALIK NOORZAI', 'MALIK NOORZAI', 'Taliban', 'TAi.154', '2011-10-04', 'Afghanistan', 'Boghra Road, Miralzei Village, Chaman, Baluchistan Province, Pakistan; Kalay Rangin, Spin Boldak District, Kandahar province, Afghanistan', 'Taliban financier. Owns businesses in Japan and frequently travels to Dubai, United Arab Emirates, and Japan. As of 2009, facilitated Taliban activities, including through recruitment and the provision of logistical support. Belongs to Noorzai tribe. Brother of Faizullah Khan Noorzai (TAi.153). Father’s name is Haji Akhtar Muhammad INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2975591', 'individual', 'ABDUL AZIZ ABBASIN', 'ABDUL AZIZ ABBASIN', 'Taliban', 'TAi.155', '2011-10-04', NULL, NULL, 'Key commander in the Haqqani Network (TAe.012) under Sirajuddin Jallaloudine Haqqani (TAi.144). Taliban Shadow Governor for Orgun District, Paktika Province as of early 2010. Operated a training camp for non-Afghan fighters in Paktika Province. Has been involved in the transport of weapons to Afghanistan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2981707', 'individual', 'AHMAD ZIA AGHA', 'AHMAD ZIA AGHA', 'Taliban', 'TAi.156', '2012-01-06', 'Afghanistan', 'Kabul, Afghanistan', 'Senior Taliban official with military and financial responsibilities as at 2011. Leader of the Taliban’s Military Council as of 2010. In 2008 and 2009, served as a Taliban finance officer and distributed money to Taliban commanders in Afghanistan/Pakistan border area. Height: 180 cm. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2981583', 'individual', 'FAZL RABI', 'FAZL RABI', 'Taliban', 'TAi.157', '2012-01-06', 'Afghanistan', NULL, 'Represents and provides financial and logistical support to the Haqqani Network (TAe.012), which is based in Afghanistan/Pakistan border area. Member of the Taliban Financial Council. Has travelled abroad to raise funds on behalf of Sirajuddin Jallaloudine Haqqani (TAi.144), Jalaluddin Haqqani (TAi.040), the Haqqani network and the Taliban. Believed to be in Afghanistan/Pakistan border area INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2981821', 'individual', 'MOHAMMAD AMAN AKHUND', 'MOHAMMAD AMAN AKHUND', 'Taliban', 'TAi.158', '2012-01-06', NULL, NULL, 'Senior Taliban member as at 2011 with financial duties, including raising funds on behalf of the leadership. Has provided logistical support for Taliban operations and channeled proceeds from drug trafficking to arms purchases. Has acted as secretary to Taliban leader Mullah Mohammed Omar (TAi.004) and as his messenger at senior-level meetings of the Taliban. Also associated with Gul Agha Ishakzai (TAi.147). Member of Mullah Mohammed Omar’s (TAi.004) inner circle during the Taliban regime INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2981584', 'individual', 'AHMED JAN WAZIR AKHTAR MOHAMMAD', 'AHMED JAN WAZIR AKHTAR MOHAMMAD', 'Taliban', 'TAi.159', '2012-01-06', NULL, NULL, 'Key commander of the Haqqani Network (TAe.012), which is based in Afghanistan/Pakistan border area. Acts as deputy, spokesperson and advisor for Haqqani Network senior leader Sirajuddin Jallaloudine Haqqani (TAi.144). Liaises with the Taliban Supreme Council. Has travelled abroad. Liaises with and provides Taliban commanders in Ghazni Province, Afghanistan, with money, weapons, communications equipment and supplies. Reportedly deceased as of 2013 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2983128', 'individual', 'ABDUL SAMAD ACHEKZAI', 'ABDUL SAMAD ACHEKZAI', 'Taliban', 'TAi.160', '2012-03-02', 'Afghanistan', NULL, 'Senior Taliban member responsible for the manufacturing of improvised explosive devices (IED). Involved in recruiting and deploying suicide bombers to conduct attacks in Afghanistan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2989151', 'individual', 'BAKHT GUL', 'BAKHT GUL', 'Taliban', 'TAi.161', '2012-06-27', 'Afghanistan', 'Miram Shah, North Waziristan, Federally Administered Tribal Areas, Pakistan', 'Communications assistant to Badruddin Haqqani (deceased). Also coordinates movement of Haqqani insurgents, foreign fighters and weapons in the Afghanistan/Pakistan border area. Belongs to Zadran tribe INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2989674', 'individual', 'ABDUL SATAR ABDUL MANAN', 'ABDUL SATAR ABDUL MANAN', 'Taliban', 'TAi.162', '2012-06-29', NULL, 'Kachray Road, Pashtunabad, Quetta, Baluchistan Province, Pakistan; Nasrullah Khan Chowk, Pashtunabad Area, Baluchistan Province, Pakistan; Chaman, Baluchistan Province, Pakistan; Abdul Satar Food Shop, Ayno Mina 0093, Kandahar Province, Afghanistan', 'Co-owner of Haji Khairullah Haji Sattar Money Exchange (TAe.010) and associated also with Khairullah Barakzai (TAi.163). Belongs to Barakzai tribe. Father’s name is Hajji ‘Abd-al-Manaf INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('2989740', 'individual', 'KHAIRULLAH BARAKZAI KHUDAI NAZAR', 'KHAIRULLAH BARAKZAI KHUDAI NAZAR', 'Taliban', 'TAi.163', '2012-06-29', NULL, 'Abdul Manan Chowk, Pashtunabad, Quetta, Baluchistan Province, Pakistan', 'Co-owner of Haji Khairullah Haji Sattar Money Exchange (TAe.010) and associated also with Abdul Satar Abdul Manan (TAi.162). Belongs to Barakzai tribe. Father’s name is Haji Khudai Nazar. Alternative father’s name is Nazar Mohammad INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('3000769', 'individual', 'ABDUL RAUF ZAKIR', 'ABDUL RAUF ZAKIR', 'Taliban', 'TAi.164', '2012-11-05', 'Afghanistan', NULL, 'Chief of suicide operations for the Haqqani Network (TAe.012) under Sirajuddin Jallaloudine Haqqani (TAi.144) and in charge of all operations in Kabul, Takhar, Kunduz and Baghlan provinces. Oversees training of suicide attackers and provides instructions on how to construct improvised explosives devices (IEDs). Reportedly deceased as of 22 September 2018 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('3000509', 'individual', 'MOHAMMED QASIM MIR WALI KHUDAI RAHIM', 'MUHAMMAD QASIM MIR WALI KHUDAI RAHIM', 'Taliban', 'TAi.165', '2012-11-21', 'Afghanistan', 'Wesh, Spin Boldak District, Kandahar Province, Afghanistan; Safaar Bazaar, Garmser District, Helmand Province, Afghanistan; Room number 33, 5th Floor Sarafi Market, Kandahar City, Kandahar Province, Afghanistan', 'Owner of Rahat Ltd. (TAe.013). Involved in the supply of weapons for Taliban, including improvised explosive devices (IED). Arrested in 2012 and in custody in Afghanistan as of January 2013. Associated with Rahat Ltd. (TAe.013) INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('3013137', 'individual', 'AHMED SHAH NOORZAI OBAIDULLAH', 'AHMED SHAH NOORZAI OBAIDULLAH', 'Taliban', 'TAi.166', '2013-02-26', NULL, 'Quetta, Pakistan', 'Owns and operates the Roshan Money Exchange (TAe.011). Provided financial services to Ghul Agha Ishakzai (TAi.147) and other Taliban in Helmand Province. Alternative title is Maulavi INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('3016479', 'individual', 'ADAM KHAN ACHEKZAI', 'ADAM KHAN ACHEKZAI', 'Taliban', 'TAi.167', '2013-04-16', 'Pakistan', 'Chaman, Baluchistan Province, Pakistan', 'Improvised explosive device manufacturer and facilitator for the Taliban. Taliban member responsible for Badghis Province, Afghanistan, as at mid – 2010. Former Taliban member responsible for Sar-e Pul and Samangan Provinces, Afghanistan. As Taliban military commander in Kandahar Province, Afghanistan, he was involved in organizing suicide attacks in neighboring provinces. Associated with Abdul Samad Achekzai (TAi.160) INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('3035783', 'individual', 'QARI SAIFULLAH TOKHI', 'QARI SAIFULLAH TOKHI', 'Taliban', 'TAi.168', '2014-03-19', 'Afghanistan', 'Chalo Bawari area, Quetta City, Baluchistan Province, Pakistan', 'Believed to be in Afghanistan/Pakistan border area. Taliban Shadow Deputy Governor and operational commander in Zabul Province, Afghanistan, responsible for the laying of improvised explosive devices and the organisation of suicide attacks. Physical description: height: 180 cm; weight: approximately 90 kg; build: athletic build; eye colour: brown; hair colour: red; complexion: medium brown. Distinguishing physical marks: large round face, full beard, and walks with a limp due to plastic prosthesis in place of his left lower leg. Ethnic background: Pashtun; Belongs to Tokhi tribe, Barkozai sub-tribe (alternative tribe spelling: Torchi). Barkozai (alternative tribe spelling: Bakorzai, باکورزی) sub-tribe, Kishta Barkorzai (lower Barkorzai) clan. Marital Status: married. Father’s name: Agha Mohammad. Brother’s name: Humdullah INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908403', 'individual', 'YAHYA HAQQANI', 'YAHYA HAQQANI', 'Taliban', 'TAi.169', '2014-07-31', 'Afghanistan', 'A Haqqani Madrassa in the Afghanistan/Pakistan Border Area.', 'Senior Haqqani Network (HQN) (TAe.012) member. Closely involved in the group’s military, financial, and propaganda activities. Injured leg. Father’s name is Hajji Meyawar Khan (deceased) INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908404', 'individual', 'SAIDULLAH JAN', 'SAIDULLAH JAN', 'Taliban', 'TAi.170', '2014-07-31', NULL, NULL, 'Senior member of the Haqqani Network (HQN) (TE.H.12.12.) as of 2013. Provided critical facilitation support to drivers and vehicles transporting HQN ammunition. Also involved in the group’s recruiting efforts as of 2011. Father’s name is Bakhta Jan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908405', 'individual', 'MUHAMMAD OMAR ZADRAN', 'MUHAMMAD OMAR ZADRAN', 'Taliban', 'TAi.171', '2014-07-31', NULL, 'Afghanistan/Pakistan Border Area', 'Haqqani Network (HQN) (TAe.012) leader in command of over 100 militants active in Khost Province, Afghanistan as of 2013. Involved in the preparation of attacks against Afghan and international forces in Afghanistan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908406', 'individual', 'RAHMATULLAH SHAH NAWAZ', 'RAHMATULLAH SHAH NAWAZ', 'Taliban', 'TAi.172', '2014-08-21', 'Afghanistan', 'Kamkai Village, Achin District, Nangarhar Province, Afghanistan; Kamkai Village, Achin District, Nangarhar Province, Afghanistan; Surkhel village, Achin District, Nangarhar Province, Afghanistan; Batan village, Achin District, Nangarhar Province, Afghanistan', 'Physical description: eye colour brown, hair colour: black, weight: 77-81 kg, height: 178 cm short-to-medium black beard, short black hair. Belongs to Shinwari tribe, Sepahi sub-tribe. A Taliban commander since at least Feb. 2010. Collects taxes and bribes on behalf of the Taliban as of April 2015. Liaises with and provides Taliban operatives in Nangarhar Province, Afghanistan, with information, guidance, housing and weapons and has emplaced improvised explosive devices (IED) and conducted attacks against International Security Assistance Force (ISAF) and Afghan forces. Involved in drug trafficking and operates heroin laboratory in Abdulkhel village, Achin district, Nangarhar province, Afghanistan INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908450', 'individual', 'ABDUL BASIR NOORZAI', 'ABDUL BASIR NOORZAI', 'Taliban', 'TAi.173', '2015-03-27-04:00', 'Afghanistan', 'Chaman, Baluchistan Province, Pakistan', 'Owner of Haji Basir and Zarjmil Company Hawala (TAe.014), which provides financial services to Taliban in the region INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
('6908491', 'individual', 'TOREK AGHA', 'TOREK AGHA', 'Taliban', 'TAi.174', '2015-11-02', NULL, 'Pashtunabad, Quetta, Baluchistan Province, Pakistan', 'Key commander for Taliban military council involved in fundraising from Gulf-based donors. Photo available for inclusion in the INTERPOL-UN Security Council Special Notice. Reportedly deceased as of November 2018 INTERPOL-UN Security Council Special Notice:https://www.interpol.int/en/How-we-work/Notices/View-UN-Notices-Individuals', 'https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list', 1, '2026-11-22'),
